import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import assertLiveView from '../scripts/assert-live-view.cjs';
const arg = name => { const i = process.argv.indexOf(name); return i < 0 ? undefined : process.argv[i + 1]; };
const slug = arg('--slug');
if (!slug?.startsWith('/')) throw new Error('Usage: npm run mcp:verify -- --slug /changed-page [--session id] [--since ISO-timestamp]');
const since = arg('--since') ? Date.parse(arg('--since')) : 0;
if (!Number.isFinite(since)) throw new Error('Invalid --since timestamp');
const credentialsPath = process.env.RANCH_VIEW_CREDENTIALS || path.join(os.homedir(), '.codex', 'ranch-view', 'credentials.json');
const { url } = JSON.parse(fs.readFileSync(credentialsPath, 'utf8'));
const response = await fetch(new URL('/view-build.json', url), { cache: 'no-store', signal: AbortSignal.timeout(15000) });
if (!response.ok) throw new Error('Deployed MCP build manifest is unavailable');
const manifest = await response.json();
const localManifest = JSON.parse(fs.readFileSync(new URL('../view-build.json', import.meta.url), 'utf8'));
const expectedBuild = arg('--build') || localManifest.buildId;
if (manifest.buildId !== expectedBuild) throw new Error('Deployed build differs from the expected build. With concurrent source edits, pass --build using the exact build ID from the successful Vercel build log.');
const client = new Client({ name: 'ranch-view-verification', version: '2.0.0' });
const timeout = setTimeout(() => { console.error('MCP verification timed out'); process.exit(1); }, 45000);
await client.connect(new StdioClientTransport({ command: process.execPath, env: {...process.env}, args: [fileURLToPath(new URL('./ranch-view.mjs', import.meta.url))] }));
try {
  const tools = (await client.listTools()).tools.map(t => t.name);
  for (const expected of ['get_current_view','get_view_image','list_views']) if (!tools.includes(expected)) throw new Error('Missing MCP tool: ' + expected);
  const listed = await client.callTool({ name: 'list_views', arguments: {} });
  if (listed.isError) throw new Error('MCP list_views failed');
  const views = JSON.parse(listed.content[0].text);
  const target = arg('--session') || views.find(v => v.slug === slug && !v.stale && v.buildId === manifest.buildId)?.sessionId;
  if (!target) throw new Error(`No fresh ${slug} view for this build. Pair/reload the changed page and retry.`);
  const current = await client.callTool({ name: 'get_current_view', arguments: { sessionId: target } });
  if (current.isError) throw new Error('MCP get_current_view failed');
  const view = JSON.parse(current.content[0].text);
  assertLiveView(view, { slug, buildId: manifest.buildId, since });
  const imageResult = await client.callTool({ name: 'get_view_image', arguments: { sessionId: view.sessionId } });
  const image = imageResult.content.find(c => c.type === 'image');
  if (imageResult.isError) throw new Error('MCP get_view_image failed');
  const imageContext = JSON.parse(imageResult.content[0].text);
  assertLiveView(imageContext, { slug, buildId: manifest.buildId, since, image: true });
  if (!image) throw new Error('MCP returned no image');
  const outputDirectory = arg('--output-dir') || path.join(os.homedir(), '.codex', 'ranch-view');
  fs.mkdirSync(outputDirectory, { recursive: true });
  const destination = path.join(outputDirectory, 'verified-view.jpg');
  fs.writeFileSync(destination, Buffer.from(image.data, 'base64'));
  const proof = { passed: true, origin: new URL(url).origin, checkedAt: new Date().toISOString(), buildId: manifest.buildId, sessionId: target, slug: view.slug, ageSeconds: view.ageSeconds, imageAgeSeconds: imageContext.imageAgeSeconds, context: view.context, errors: view.errors };
  fs.writeFileSync(path.join(outputDirectory, 'last-verification.json'), JSON.stringify(proof, null, 2));
  console.log(JSON.stringify(proof, null, 2));
  console.log('MCP image verified:', destination);
} finally { clearTimeout(timeout); await client.close(); }
